CREATE OR REPLACE FUNCTION pr_training_internal.sync_completed_checks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 BEGIN
  IF TG_OP='DELETE' THEN
   DELETE FROM public.pr_training_public_checks WHERE profile_id=old.profile_id AND task_id=old.task_id;
   RETURN old;
  END IF;
  IF lower(coalesce(new.status,''))='completed' AND new.completed_at IS NOT NULL THEN
   INSERT INTO public.pr_training_public_checks(profile_id,task_id,completed_at,updated_at)
   VALUES(new.profile_id,new.task_id,new.completed_at,now())
   ON CONFLICT(profile_id,task_id) DO UPDATE SET completed_at=excluded.completed_at,updated_at=excluded.updated_at;
  ELSE
   DELETE FROM public.pr_training_public_checks WHERE profile_id=new.profile_id AND task_id=new.task_id;
  END IF;
  RETURN new;
 END $function$
;
ALTER FUNCTION "pr_training_internal"."sync_completed_checks"() OWNER TO "postgres";
REVOKE ALL ON FUNCTION "pr_training_internal"."sync_completed_checks"() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "pr_training_internal"."sync_completed_checks"() TO "postgres";
CREATE OR REPLACE FUNCTION public.admin_list_student_access_requests()
 RETURNS SETOF student_access_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.profiles where auth_user_id=auth.uid() and role='admin') then raise exception 'No autorizado'; end if;
  return query select * from public.student_access_requests order by created_at desc;
end; $function$
;
