CREATE OR REPLACE FUNCTION public.anular_clase_particular(p_historial_id text, p_motivo text, p_modificado_por_id text, p_modificado_por_nombre text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                  declare
                                                                                                                                                                    v_cuponera_id text;
                                                                                                                                                                      v_cantidad integer;
                                                                                                                                                                        v_ultima_clase timestamptz;
                                                                                                                                                                          v_ultima_observacion text;
                                                                                                                                                                          begin
                                                                                                                                                                            if not public.soy_admin() then
                                                                                                                                                                                raise exception 'Solo un administrador puede anular clases';
                                                                                                                                                                                  end if;

                                                                                                                                                                                    if trim(coalesce(p_motivo, '')) = '' then
                                                                                                                                                                                        raise exception 'Debés indicar el motivo de la anulación';
                                                                                                                                                                                          end if;

                                                                                                                                                                                            select
                                                                                                                                                                                                h.cuponera_id::text,
                                                                                                                                                                                                    greatest(coalesce(h.cantidad, 1), 1)
                                                                                                                                                                                                      into
                                                                                                                                                                                                          v_cuponera_id,
                                                                                                                                                                                                              v_cantidad
                                                                                                                                                                                                                from public.clases_particulares_historial h
                                                                                                                                                                                                                  where h.id::text = p_historial_id
                                                                                                                                                                                                                      and h.fecha_clase is not null
                                                                                                                                                                                                                          and coalesce(h.anulado, false) = false
                                                                                                                                                                                                                            for update;

                                                                                                                                                                                                                              if v_cuponera_id is null then
                                                                                                                                                                                                                                  raise exception 'La clase no existe o ya fue anulada';
                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                      update public.clases_particulares_historial
                                                                                                                                                                                                                                        set
                                                                                                                                                                                                                                            anulado = true,
                                                                                                                                                                                                                                                motivo_correccion = trim(p_motivo),
                                                                                                                                                                                                                                                    corregido_por_id = p_modificado_por_id,
                                                                                                                                                                                                                                                        corregido_por_nombre = p_modificado_por_nombre,
                                                                                                                                                                                                                                                            corregido_en = now()
                                                                                                                                                                                                                                                              where id::text = p_historial_id;

                                                                                                                                                                                                                                                                update public.cuponeras_particulares
                                                                                                                                                                                                                                                                  set
                                                                                                                                                                                                                                                                      clases_utilizadas = greatest(
                                                                                                                                                                                                                                                                            0,
                                                                                                                                                                                                                                                                                  coalesce(clases_utilizadas, 0) - v_cantidad
                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                          clases_disponibles =
                                                                                                                                                                                                                                                                                                coalesce(clases_disponibles, 0) + v_cantidad
                                                                                                                                                                                                                                                                                                  where id::text = v_cuponera_id;

                                                                                                                                                                                                                                                                                                    select
                                                                                                                                                                                                                                                                                                        h.fecha_clase,
                                                                                                                                                                                                                                                                                                            h.observacion
                                                                                                                                                                                                                                                                                                              into
                                                                                                                                                                                                                                                                                                                  v_ultima_clase,
                                                                                                                                                                                                                                                                                                                      v_ultima_observacion
                                                                                                                                                                                                                                                                                                                        from public.clases_particulares_historial h
                                                                                                                                                                                                                                                                                                                          where h.cuponera_id::text = v_cuponera_id
                                                                                                                                                                                                                                                                                                                              and h.fecha_clase is not null
                                                                                                                                                                                                                                                                                                                                  and coalesce(h.anulado, false) = false
                                                                                                                                                                                                                                                                                                                                    order by h.fecha_clase desc, h.created_at desc
                                                                                                                                                                                                                                                                                                                                      limit 1;

                                                                                                                                                                                                                                                                                                                                        update public.cuponeras_particulares
                                                                                                                                                                                                                                                                                                                                          set
                                                                                                                                                                                                                                                                                                                                              ultima_clase = v_ultima_clase,
                                                                                                                                                                                                                                                                                                                                                  ultima_observacion = v_ultima_observacion
                                                                                                                                                                                                                                                                                                                                                    where id::text = v_cuponera_id;

                                                                                                                                                                                                                                                                                                                                                      return jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                          'ok', true,
                                                                                                                                                                                                                                                                                                                                                              'devueltas', v_cantidad,
                                                                                                                                                                                                                                                                                                                                                                  'mensaje', 'Clase anulada y devuelta al saldo'
                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                    end;
                                                                                                                                                                                                                                                                                                                                                                    $function$
;
ALTER FUNCTION "public"."anular_clase_particular"(p_historial_id text, p_motivo text, p_modificado_por_id text, p_modificado_por_nombre text) OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."anular_clase_particular"(p_historial_id text, p_motivo text, p_modificado_por_id text, p_modificado_por_nombre text) FROM PUBLIC, anon, authenticated, service_role;
