CREATE OR REPLACE FUNCTION public.assign_pr_toma_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
                                          begin
                                            if new.numero_toma is null then
                                                select coalesce(max(t.numero_toma), 0) + 1
                                                      into new.numero_toma
                                                          from public.pr_performance_tomas t
                                                              where t.alumno_id = new.alumno_id
                                                                    and t.eliminado = false;
                                                                      end if;

                                                                        return new;
                                                                        end;
                                                                        $function$
;
