CREATE OR REPLACE FUNCTION public.cargar_clases_particulares(p_alumno_id text, p_cantidad integer, p_registrado_por_id text, p_registrado_por_nombre text)
 RETURNS cuponeras_particulares
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
          declare
            v_cuponera public.cuponeras_particulares;
              v_saldo_anterior integer;
              begin
                if p_cantidad is null or p_cantidad <= 0 then
                    raise exception 'La cantidad debe ser mayor a cero.';
                      end if;

                        update public.profiles
                          set
                              particulares_habilitadas = true,
                                  updated_at = now()
                                    where id = p_alumno_id;

                                      if not found then
                                          raise exception 'Alumno no encontrado.';
                                            end if;

                                              select *
                                                into v_cuponera
                                                  from public.cuponeras_particulares
                                                    where alumno_id = p_alumno_id
                                                      for update;

                                                        if not found then
                                                            insert into public.cuponeras_particulares (
                                                                  alumno_id,
                                                                        clases_cargadas,
                                                                              clases_utilizadas,
                                                                                    clases_disponibles,
                                                                                          habilitada,
                                                                                                estado,
                                                                                                      creado_por_id,
                                                                                                            creado_por_nombre
                                                                                                                )
                                                                                                                    values (
                                                                                                                          p_alumno_id,
                                                                                                                                p_cantidad,
                                                                                                                                      0,
                                                                                                                                            p_cantidad,
                                                                                                                                                  true,
                                                                                                                                                        'activa',
                                                                                                                                                              p_registrado_por_id,
                                                                                                                                                                    p_registrado_por_nombre
                                                                                                                                                                        )
                                                                                                                                                                            returning *
                                                                                                                                                                                into v_cuponera;

                                                                                                                                                                                    v_saldo_anterior := 0;
                                                                                                                                                                                      else
                                                                                                                                                                                          v_saldo_anterior :=
                                                                                                                                                                                                v_cuponera.clases_disponibles;

                                                                                                                                                                                                    update public.cuponeras_particulares
                                                                                                                                                                                                        set
                                                                                                                                                                                                              clases_cargadas =
                                                                                                                                                                                                                      clases_cargadas + p_cantidad,
                                                                                                                                                                                                                            clases_disponibles =
                                                                                                                                                                                                                                    clases_disponibles + p_cantidad,
                                                                                                                                                                                                                                          habilitada = true,
                                                                                                                                                                                                                                                estado = 'activa',
                                                                                                                                                                                                                                                      updated_at = now()
                                                                                                                                                                                                                                                          where id = v_cuponera.id
                                                                                                                                                                                                                                                              returning *
                                                                                                                                                                                                                                                                  into v_cuponera;
                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                      insert into public.clases_particulares_historial (
                                                                                                                                                                                                                                                                          alumno_id,
                                                                                                                                                                                                                                                                              cuponera_id,
                                                                                                                                                                                                                                                                                  tipo,
                                                                                                                                                                                                                                                                                      cantidad,
                                                                                                                                                                                                                                                                                          saldo_anterior,
                                                                                                                                                                                                                                                                                              saldo_despues,
                                                                                                                                                                                                                                                                                                  registrado_por_id,
                                                                                                                                                                                                                                                                                                      registrado_por_nombre
                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                          values (
                                                                                                                                                                                                                                                                                                              p_alumno_id,
                                                                                                                                                                                                                                                                                                                  v_cuponera.id,
                                                                                                                                                                                                                                                                                                                      'carga',
                                                                                                                                                                                                                                                                                                                          p_cantidad,
                                                                                                                                                                                                                                                                                                                              v_saldo_anterior,
                                                                                                                                                                                                                                                                                                                                  v_cuponera.clases_disponibles,
                                                                                                                                                                                                                                                                                                                                      p_registrado_por_id,
                                                                                                                                                                                                                                                                                                                                          p_registrado_por_nombre
                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                              return v_cuponera;
                                                                                                                                                                                                                                                                                                                                              end;
                                                                                                                                                                                                                                                                                                                                              $function$
;
