REVOKE ALL ON FUNCTION "public"."claim_pr_mp_payment_notification"(p_attempt_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."claim_pr_mp_payment_notification"(p_attempt_id uuid) TO "postgres";
