CREATE OR REPLACE FUNCTION public.clinica_oct_2026_cupos()
 RETURNS TABLE(ocupados integer, total integer, disponibles integer, lista_espera integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    count(*) filter (where estado <> 'cancelado')::integer as ocupados,
    30::integer as total,
    greatest(30 - count(*) filter (where estado <> 'cancelado' and estado <> 'lista_espera'), 0)::integer as disponibles,
    count(*) filter (where estado = 'lista_espera')::integer as lista_espera
  from public.pr_clinica_oct_2026_inscripciones;
$function$
;
ALTER FUNCTION "public"."clinica_oct_2026_cupos"() OWNER TO "postgres";
REVOKE ALL ON FUNCTION "public"."clinica_oct_2026_cupos"() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."clinica_oct_2026_cupos"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."clinica_oct_2026_cupos"() TO "postgres";
