REVOKE ALL ON FUNCTION "public"."community_add_album_comment"(p_album_id uuid, p_body text, p_parent_comment_id uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_add_album_comment"(p_album_id uuid, p_body text, p_parent_comment_id uuid) TO "postgres";
