CREATE OR REPLACE FUNCTION public.community_add_album_photo(p_album_id uuid, p_media_path text, p_caption text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare pid text:=public.pr_current_profile_id(); photoid uuid; begin if not exists(select 1 from community_albums a where a.id=p_album_id and (a.owner_id=pid or exists(select 1 from community_album_members m where m.album_id=a.id and m.profile_id=pid and m.status='accepted'))) then raise exception 'No tenés acceso colaborativo a este álbum'; end if; insert into community_album_media(album_id,uploader_id,media_path,caption) values(p_album_id,pid,p_media_path,nullif(trim(p_caption),'')) returning id into photoid; return photoid; end $function$
;
