CREATE OR REPLACE FUNCTION public.community_answer_album_invite(p_album_id uuid, p_accept boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid text:=public.pr_current_profile_id(); ownerid text; nm text; album_title text; changed boolean; owner_name text;
begin
  update community_album_members set status=case when p_accept then 'accepted' else 'declined' end where album_id=p_album_id and profile_id=pid and status in ('pending','invited');
  changed:=found;
  if changed and p_accept then
    select a.owner_id,a.title,coalesce(p.nombre,'Punta Rollers') into ownerid,album_title,owner_name from community_albums a left join profiles p on p.id=a.owner_id where a.id=p_album_id;
    select coalesce(nombre,'Alguien') into nm from profiles where id=pid;
    if ownerid is not null and ownerid<>pid then
      insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text)
      values(ownerid,pid,'album_collab_accepted','album',p_album_id,nm||' aceptó colaborar en “'||coalesce(album_title,'tu álbum')||'” y ya puede sumar sus fotos.');
    end if;
    insert into community_notifications(recipient_id,actor_id,kind,entity_type,entity_id,text)
    values(pid,ownerid,'album_collab_ready','album',p_album_id,'Ya sos colaborador de “'||coalesce(album_title,'este álbum')||'”. El álbum ahora forma parte de tu perfil y podés sumar tus propias fotos cuando quieras.');
  end if;
  return changed;
end $function$
;
