REVOKE ALL ON FUNCTION "public"."community_answer_album_invite"(p_album_id uuid, p_accept boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION "public"."community_answer_album_invite"(p_album_id uuid, p_accept boolean) TO "postgres";
