CREATE OR REPLACE FUNCTION public.community_are_friends(a text, b text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$select a=b or exists(select 1 from community_friendships f where(f.profile_a_id=a and f.profile_b_id=b)or(f.profile_a_id=b and f.profile_b_id=a))$function$
;
