CREATE OR REPLACE FUNCTION public.community_can_view_album(p_album_id uuid, p_profile_id text DEFAULT pr_current_profile_id())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists(select 1 from community_albums a where a.id=p_album_id and (a.owner_id=p_profile_id or community_are_friends(p_profile_id,a.owner_id) or exists(select 1 from community_album_members m where m.album_id=a.id and m.profile_id=p_profile_id and m.status='accepted'))) $function$
;
